      "kind": "directOfficial",
      "sourceId": "hsk2-official-vi:l02:p012:text1-line6",
      "documentSourceId": "hsk2-official-vi-20261004",
      "pdfSHA256": "6465777a77f8d9cb0d29b47f00b36a8e9e9ff627509f0f02a9909c7aaeaa231b",
      "pdfPages": [
        26
      ],
      "printedPages": [
        12
      ],
      "section": "text1-line6",
      "zhContext": "好，没问题。",
      "officialZhText": "好，没问题。",
      "officialViText": "Được, không vấn đề gì cả."
